function supplement_c2_dynamics(out,p)
% The CSV here is this task's full1ms extraction of the original MAT, not legacy20ms.
D=readtable(fullfile(out,'tables/C2_native_diagnostic.csv'));t=D.time_s;wr=D{:,{'ref_p_radps','ref_q_radps','ref_r_radps'}};acc=zeros(size(wr));for j=1:3,acc(:,j)=gradient(wr(:,j),t);end
% Conditional feed-forward proxy at measured gyro state, not an MPC objective/feedback request.
required=(p.J*acc')'-D{:,{'disturbance_x','disturbance_y','disturbance_z'}}-D{:,{'gyro_x','gyro_y','gyro_z'}}-D{:,{'rigid_x','rigid_y','rigid_z'}};
F=table(t,required(:,2),D.pitch_control_total_Nm,D.pitch_error_deg,'VariableNames',{'time_s','reference_acceleration_pitch_control_proxy_Nm','actual_aero_plus_CMG_pitch_Nm','pitch_error_deg'});writetable(F,fullfile(out,'tables/C2_required_torque_native.csv'));
segments=[0 8;8 12;12 20;20 24;24 32;32 36;36 46];rows={};for j=1:7,mask=t>=segments(j,1)&t<segments(j,2);v=struct('start_s',segments(j,1),'end_s',segments(j,2),'required_proxy_min_Nm',min(required(mask,2)),'required_proxy_max_Nm',max(required(mask,2)),'proxy_positive_samples',sum(required(mask,2)>0),'proxy_negative_samples',sum(required(mask,2)<0),'actual_control_proxy_error_rms_Nm',sqrt(mean((required(mask,2)-D.pitch_control_total_Nm(mask)).^2)));rows{end+1}=v;end;writetable(struct2table([rows{:}]),fullfile(out,'tables/C2_required_torque_segments.csv'));
f=figure('Visible','off');tiledlayout(4,1);nexttile;plot(t,D.pitch_deg,t,D.ref_pitch_deg,'--');ylabel('Pitch (deg)');legend('actual','reference');nexttile;plot(t,D.pitch_error_deg);ylabel('Pitch error (deg)');nexttile;plot(t,[D.aero_y D.cmg_y D.pitch_control_total_Nm required(:,2)]);ylabel('Moment (N m)');legend('actual aero incl natural','actual CMG','aero+CMG','reference-acceleration proxy');nexttile;plot(t,[D.natural_y D.disturbance_y D.gyro_y D.rigid_y D.net_y]);ylabel('Dynamics (N m)');legend('natural aero','disturbance','-omega x H','-omega x Jomega','net Jomegadot');axs=findall(f,'Type','axes');for j=1:numel(axs),axes(axs(j));grid on;xlim([0 46]);for on=[8 20 32],xline(on,'k:','HandleVisibility','off');xline(on+4,'k--','HandleVisibility','off');end;end;xlabel('Time (s)');nexttile(1);legend({'actual','reference'},'Location','best','AutoUpdate','off');nexttile(3);legend({'actual aero incl natural','actual CMG','aero+CMG','reference-acceleration proxy'},'Location','best','AutoUpdate','off');nexttile(4);legend({'natural aero','disturbance','-omega x H','-omega x Jomega','net Jomegadot'},'Location','best','AutoUpdate','off');label_c2_figure('pitch');v3_savefig(f,out,'C2_pitch_error_and_torque');
paper_json(fullfile(out,'config/physical_parameters.json'),struct('J',p.J,'vehicle',p.vehicle,'cmg',p.cmg));
end
